import{_ as i,c as a,o as s,ah as r,j as e,a as t}from"./chunks/framework.oAolcYhj.js";const l="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit.jpg",o="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_table.jpg",h="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_search.jpg",d="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_search_columns.jpg",c="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_add.jpg",u="/Qonnectra-docs/pr-14/videos/conduit_add.webm",g="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_properties.jpg",p="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_status.jpg",m="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_attachment.jpg",b="/Qonnectra-docs/pr-14/images/manual/teil-a/conduit_excel.jpg",D=JSON.parse('{"title":"6. Rohrverwaltung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/06-rohrverwaltung.md","filePath":"manual/teil-a-anwenderhandbuch/06-rohrverwaltung.md"}'),f={name:"manual/teil-a-anwenderhandbuch/06-rohrverwaltung.md"};function S(k,n,R,_,w,v){return s(),a("div",null,[...n[0]||(n[0]=[r('<h1 id="_6-rohrverwaltung" tabindex="-1">6. Rohrverwaltung <a class="header-anchor" href="#_6-rohrverwaltung" aria-label="Permalink to &quot;6. Rohrverwaltung&quot;">​</a></h1><p>Die <strong>Rohrverwaltung</strong> führt alle Rohre des ausgewählten Projekts in einer Tabelle auf. Hier legen Sie neue Rohre an, bearbeiten vorhandene, hinterlegen Anhänge und übernehmen größere Bestände aus einer Excel-Datei. Sie erreichen sie über die linke Navigation in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Verwaltung“.</p><p><img src="'+l+'" alt="Screenshot Rohrverwaltung mit der Tabelle aller Rohre" data-zoomable="true"></p><p>Welche Rohre die Tabelle enthält, hängt von dem Projekt ab, das oben links in der Kopfzeile ausgewählt ist.</p><h2 id="_6-1-aufbau-der-tabelle" tabindex="-1">6.1 Aufbau der Tabelle <a class="header-anchor" href="#_6-1-aufbau-der-tabelle" aria-label="Permalink to &quot;6.1 Aufbau der Tabelle&quot;">​</a></h2><p>Zu jedem Rohr zeigt die Tabelle die Spalten „Name“, „Rohrtyp“, „Schutzrohr“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Datum“ und „Kennzeichen“.</p><p>Ein Klick auf eine Spaltenüberschrift sortiert die Tabelle nach dieser Spalte: der erste Klick aufsteigend, der zweite absteigend, der dritte hebt die Sortierung wieder auf.</p><p>Eine Seite umfasst 50 Rohre; unter der Tabelle stehen die Gesamtzahl und die Seitenauswahl.</p><p><img src="'+o+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Spaltenüberschriften und der Seitenauswahl unten rechts" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Sortierung ordnet nur die Rohre der angezeigten Seite. Bei mehr als einer Seite bleibt ein Rohr von einer anderen Seite also außen vor – auch wenn es alphabetisch an erster Stelle stünde.</p></div><h2 id="_6-2-suchen-und-filtern" tabindex="-1">6.2 Suchen und Filtern <a class="header-anchor" href="#_6-2-suchen-und-filtern" aria-label="Permalink to &quot;6.2 Suchen und Filtern&quot;">​</a></h2><p>Zum Eingrenzen der Tabelle stehen zwei Suchfunktionen zur Verfügung, die sich in ihrer Reichweite unterscheiden.</p><p><strong>Suchfeld oben</strong></p><p>Das Suchfeld neben „Rohr hinzufügen“ durchsucht alle Rohre des Projekts. Geben Sie einen Suchbegriff ein und drücken Sie Enter oder klicken Sie auf das Lupensymbol. Die Tabelle enthält danach nur noch die passenden Rohre, und die Gesamtzahl passt sich an. Um wieder alle Rohre zu sehen, leeren Sie das Feld und lösen die Suche erneut aus.</p><p><img src="'+h+'" alt="Screenshot Rohrverwaltung mit Hervorhebung des Suchfeldes oben; die Tabelle darunter zeigt nur noch die drei Treffer" data-zoomable="true"></p><p><strong>Suchfelder unter den Spaltenüberschriften</strong></p><p>Unter jeder Spaltenüberschrift liegt ein eigenes Suchfeld. Diese Felder arbeiten bereits beim Tippen, ohne Enter, und lassen sich miteinander kombinieren: Ein Rohr bleibt nur stehen, wenn es zu allen ausgefüllten Feldern passt. Zum Aufheben leeren Sie die Felder wieder.</p><p><img src="'+d+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Suchfelder unter den Spaltenüberschriften" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Spaltensuche durchsucht nur die angezeigte Seite. Ein Rohr, das auf einer anderen Seite steht, finden Sie damit nicht – dafür ist das Suchfeld oben zuständig. Die Gesamtzahl bleibt dabei unverändert, sie zählt weiterhin alle Rohre des Projekts.</p></div><h2 id="_6-3-rohr-hinzufugen" tabindex="-1">6.3 Rohr hinzufügen <a class="header-anchor" href="#_6-3-rohr-hinzufugen" aria-label="Permalink to &quot;6.3 Rohr hinzufügen&quot;">​</a></h2><p>Klicken Sie auf „Rohr hinzufügen“. Es öffnet sich ein Dialog mit denselben Angaben, die auch die Tabelle zeigt. Ausgefüllt sein müssen „Name“, „Rohrtyp“ und „Kennzeichen“; solange eines dieser Felder leer ist, lässt sich der Dialog nicht speichern. Der Name muss innerhalb des Projekts eindeutig sein.</p><p><img src="'+c+'" alt="Screenshot des Dialogs „Rohr hinzufügen“ mit den Eingabefeldern für ein neues Rohr" data-zoomable="true"></p><p>Nach dem Klick auf „Speichern“ bleibt der Dialog geöffnet und behält alle eingetragenen Werte. So legen Sie mehrere gleichartige Rohre nacheinander an, indem Sie nur den Namen ändern. Über „Schließen“ verlassen Sie den Dialog. Das neue Rohr steht zunächst oben in der Tabelle; beim nächsten Laden der Seite sortiert es sich alphabetisch ein.</p>',23),e("p",null,[e("video",{src:u,controls:"",playsinline:"",preload:"metadata"},[t(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_add.webm",download:""},"herunterladen"),t(" anstelle des Videos. ")])],-1),r('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Angaben des zuletzt angelegten Rohrs bleiben erhalten und stehen beim nächsten Öffnen des Dialogs wieder im Formular – auch nach einem Neustart des Browsers.</p></div><p>Aus dem gewählten Rohrtyp entstehen dabei zugleich die Mikrorohre des Rohrs, siehe Abschnitt <a href="#_6-4-2-reiter-„status">Reiter „Status“</a>.</p><h2 id="_6-4-rohr-bearbeiten" tabindex="-1">6.4 Rohr bearbeiten <a class="header-anchor" href="#_6-4-rohr-bearbeiten" aria-label="Permalink to &quot;6.4 Rohr bearbeiten&quot;">​</a></h2><p>Klicken Sie ein Rohr in der Tabelle an, öffnet sich rechts eine Box mit dem Namen des Rohrs als Überschrift. Am linken Rand der Box stehen die drei Reiter „Eigenschaften“, „Status“ und „Anhänge“ untereinander.</p><p>Die Box überdeckt den rechten Teil der Tabelle. Sie verhält sich wie die Info-Box der Karte (siehe Kapitel <a href="./05-karte.html">Karte</a>); die dort eingestellte Breite gilt für beide Ansichten.</p><h3 id="_6-4-1-reiter-„eigenschaften" tabindex="-1">6.4.1 Reiter „Eigenschaften“ <a class="header-anchor" href="#_6-4-1-reiter-„eigenschaften" aria-label="Permalink to &quot;6.4.1 Reiter „Eigenschaften“&quot;">​</a></h3><p>Hier ändern Sie die Angaben des ausgewählten Rohrs. Die Schaltflächen „Speichern“ und „Rohr löschen“ liegen am unteren Rand der Box und bleiben dort stehen; für die letzten Felder des Formulars scrollen Sie in der Box nach unten.</p><p><img src="'+g+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Box zum Bearbeiten eines Rohrs im Reiter „Eigenschaften“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Auswahlfelder – „Rohrtyp“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“ und „Kennzeichen“ – sind beim Öffnen leer, auch wenn das Rohr dort Werte hat. Die aktuellen Werte lesen Sie in der Tabelle ab. Ein leeres Auswahlfeld löscht beim Speichern nichts: Überschrieben wird nur, was Sie tatsächlich auswählen.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Speichern Sie Ihre Änderungen, bevor Sie ein anderes Rohr aus der Tabelle auswählen. Andernfalls gehen sie ohne Warnung verloren.</p></div><p>Über „Rohr löschen“ entfernen Sie das Rohr; die Rückfrage bestätigen Sie mit „Löschen“. Ob Sie ein Rohr löschen dürfen, hängt von Ihren Rechten ab – fehlt die Berechtigung, erscheint eine Fehlermeldung.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Mit dem Rohr verschwinden auch seine Mikrorohre und seine Zuordnungen zu Trassensegmenten (siehe Kapitel <a href="./07-rohrzuordnung.html">Rohrzuordnung</a>). Rückgängig machen lässt sich das nicht.</p></div><h3 id="_6-4-2-reiter-„status" tabindex="-1">6.4.2 Reiter „Status“ <a class="header-anchor" href="#_6-4-2-reiter-„status" aria-label="Permalink to &quot;6.4.2 Reiter „Status“&quot;">​</a></h3><p>Der Reiter listet die <strong>Mikrorohre</strong> des Rohrs auf, mit den Spalten „#“, „Farbe“, „Adresse“ (des angeschlossenen Netzknotens), „Kabel“ und „Status“. Anzahl und Farben gibt der Rohrtyp vor; ändern lassen sie sich hier nicht.</p><p><img src="'+p+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Box im Reiter „Status“ mit der Liste der Mikrorohre" data-zoomable="true"></p><p>Der Status jedes Mikrorohrs steht auf „Intakt“, solange nichts anderes eingetragen ist. Über das Auswahlfeld in der Zeile vermerken Sie eine Störung, etwa „Defekt“. Diese Änderung wird sofort übernommen, es gibt dafür keinen „Speichern“-Button.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ändern Sie den Rohrtyp nachträglich, bleibt die Liste der Mikrorohre unverändert – sie richtet sich nach dem Rohrtyp zum Zeitpunkt des Anlegens.</p></div><h3 id="_6-4-3-reiter-„anhange" tabindex="-1">6.4.3 Reiter „Anhänge“ <a class="header-anchor" href="#_6-4-3-reiter-„anhange" aria-label="Permalink to &quot;6.4.3 Reiter „Anhänge“&quot;">​</a></h3><p>Zu jedem Rohr können Sie Dateien ablegen, etwa Bestandspläne oder Messprotokolle. Hochladen, Herunterladen, Umbenennen und Löschen funktionieren wie bei den Kartenobjekten, siehe Abschnitt <a href="./05-karte.html#_5-3-1-anhange-von-kartenobjekten">Anhänge von Kartenobjekten</a>.</p><p><img src="'+m+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Box im Reiter „Anhänge“ mit einer hochgeladenen Datei" data-zoomable="true"></p><h2 id="_6-5-excel-vorlage-und-datenimport" tabindex="-1">6.5 Excel-Vorlage und Datenimport <a class="header-anchor" href="#_6-5-excel-vorlage-und-datenimport" aria-label="Permalink to &quot;6.5 Excel-Vorlage und Datenimport&quot;">​</a></h2><p>Oben rechts finden Sie zwei Schaltflächen für die Arbeit mit Excel-Dateien. „Vorlage“ lädt eine Excel-Datei mit den Spalten „Name“, „Typ“, „Schutzrohr“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Datum“, „Projekt“ und „Kennzeichen“ herunter. „Excel Import“ öffnet die Dateiauswahl; sobald Sie eine Datei gewählt haben, startet der Import ohne weitere Rückfrage.</p><p><img src="'+b+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Schaltflächen „Excel Import“ und „Vorlage“ oben rechts" data-zoomable="true"></p><p>Für die Datei gilt:</p><ul><li>Sie muss im Format .xlsx vorliegen und darf höchstens 10 MB groß sein.</li><li>Die erste Zeile enthält die Spaltenüberschriften der Vorlage. Spalten, die dort nicht vorkommen, werden übergangen; darauf weist eine Meldung hin.</li><li>In der zweiten Zeile der Vorlage steht eine Beispielzeile. Überschreiben oder löschen Sie sie, sonst versucht der Import, sie als Rohr anzulegen.</li><li>Zu welchem Projekt ein Rohr gehört, entscheidet die Spalte „Projekt“ – nicht das Projekt, das in der Kopfzeile ausgewählt ist.</li><li>Die Werte in „Typ“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Projekt“ und „Kennzeichen“ müssen in Qonnectra bereits vorhanden sein und genauso geschrieben werden wie dort.</li><li>Bleibt die Spalte „Typ“ leer, entsteht das Rohr ohne Mikrorohre.</li></ul><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Import ist ein Alles-oder-nichts-Vorgang: Ist eine einzige Zeile fehlerhaft, wird keine einzige Zeile übernommen. Die Meldung nennt die betroffene Zeilennummer und den Grund. Zurückgewiesen werden unter anderem Zeilen ohne Namen und Namen, die es in Qonnectra bereits gibt – auch in einem anderen Projekt.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Nach einem erfolgreichen Import nennt die Meldung die Anzahl der übernommenen Rohre; die Tabelle aktualisiert sich anschließend von selbst.</p></div>',27)])])}const T=i(f,[["render",S]]);export{D as __pageData,T as default};
